    //DMA Channel selection,Address Enabled and upper 16 bits[47:32] of the 2nd 6-byte MAC address Programming
    write_reg(mizar_ETHERNET1_MAC_ADDRESS3_HIGH,0x80033607); //addr_en and dma_channel_sel = 3 and addr[47:32] = 3607
    write_reg(mizar_ETHERNET1_MAC_ADDRESS2_HIGH,0x80022607); //addr_en and dma_channel_sel = 2 and addr[47:32] = 2607
    write_reg(mizar_ETHERNET1_MAC_ADDRESS1_HIGH,0x80011607);
    write_reg(mizar_ETHERNET1_MAC_ADDRESS0_HIGH,0x80000607);

    //lower 32 bits of the 2nd 6-byte MAC address
    write_reg(mizar_ETHERNET1_MAC_ADDRESS3_LOW,0x08090a00); //addr[31:0]
    write_reg(mizar_ETHERNET1_MAC_ADDRESS2_LOW,0x08090a00);
    write_reg(mizar_ETHERNET1_MAC_ADDRESS1_LOW,0x08090a00);
    write_reg(mizar_ETHERNET1_MAC_ADDRESS0_LOW,0x08090a00);

    write_reg(mizar_ETHERNET1_MAC_PACKET_FILTER,0x80000400);   //MAC_PACKET_FILTER =>  HASH FILTER Enabled and Receive All packets regardless of filter

    write_reg(mizar_ETHERNET1_MAC_CONFIGURATION,0x2003); 	//MAC_CONFIGURATION REGISTER i.e Enabling TX and RX ,Full Duplex mode selected,Speed

    write_reg(mizar_ETHERNET1_MAC_EXT_CONFIGURATION,0x0);

    //MTL Register programming

    write_reg(mizar_ETHERNET1_MTL_TXQ3_OPERATION_MODE,0x000f000a);//4096 Bytes TX QUEUE Size,STR&FWD Enabled,TX Q3 not Enabled
    write_reg(mizar_ETHERNET1_MTL_TXQ2_OPERATION_MODE,0x000f000a);//4096 Bytes TX QUEUE Size,STR&FWD Enabled,TX Q2 not Enabled
    write_reg(mizar_ETHERNET1_MTL_TXQ1_OPERATION_MODE,0x000f000a);//4096 Bytes TX QUEUE Size,STR&FWD Enabled,TX Q1 not Enabled
    write_reg(mizar_ETHERNET1_MTL_TXQ0_OPERATION_MODE,0x000f000a);//4096 Bytes TX QUEUE Size,STR&FWD Enabled,TX Q0 Enabled

    write_reg(mizar_ETHERNET1_MTL_TXQ3_QUANTUM_WEIGHT,0x00000005);//Quamtum/Weight Values need to be programmed based on WRR,WFQ,DWRR
    write_reg(mizar_ETHERNET1_MTL_TXQ2_QUANTUM_WEIGHT,0x00000005);//Quamtum/Weight Values need to be programmed based on WRR,WFQ,DWRR
    write_reg(mizar_ETHERNET1_MTL_TXQ1_QUANTUM_WEIGHT,0x00000005);//Quamtum/Weight Values need to be programmed based on WRR,WFQ,DWRR
    write_reg(mizar_ETHERNET1_MTL_TXQ0_QUANTUM_WEIGHT,0x00000005);//Quamtum/Weight Values need to be programmed based on WRR,WFQ,DWRR

